#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string t;
    cin >> t;
    string p;
    cin >> p;

    string c = p + "#" + t;
    vector<int> pi = prefixFunction(c);
    int m = (int)p.size();
    vector<int> positions;
    for (int i = m + 1; i < (int)c.size(); i++) if (pi[i] == m) positions.push_back(i - 2 * m + 1);
    cout << positions.size();
    for (int x : positions) cout << " " << x;
    cout << "\n";

    return 0;
}

